int *parent, *sz;
int *head_adj, *to, *adj_next;
int *comp_head, *comp_next;
int *deg;

int find(int x) {
    int r = x;
    while (parent[r] != r) r = parent[r];
    while (parent[x] != x) {
        int p = parent[x];
        parent[x] = r;
        x = p;
    }
    return r;
}

void unite(int a, int b) {
    a = find(a);
    b = find(b);
    if (a == b) return;
    if (sz[a] < sz[b]) {
        int t = a;
        a = b;
        b = t;
    }
    parent[b] = a;
    sz[a] += sz[b];
}

