        deg[u]++;
        deg[v]++;

        to[ec] = v;
        adj_next[ec] = head_adj[u];
        head_adj[u] = ec++;

        to[ec] = u;
        adj_next[ec] = head_adj[v];
        head_adj[v] = ec++;
    }

    long long *edge_count = (long long*)calloc(N + 1, sizeof(long long));
    for (int i = 0; i < M; i++) {
        int r = find(eu[i]);
        edge_count[r]++;
    }

    comp_head = (int*)calloc(N + 1, sizeof(int));
    comp_next = (int*)malloc((N + 1) * sizeof(int));

    for (int v = 1; v <= N; v++) {
        int r = find(v);
        comp_next[v] = comp_head[r];
        comp_head[r] = v;
    }

    int root = -1;
    for (int v = 1; v <= N; v++) {
        if (parent[v] == v) {
            long long S = sz[v];
            long long needed = S * (S - 1) / 2;
            if (edge_count[v] < needed) {
                root = v;
                break;
            }
        }
    }

    if (root == -1) {
        printf("-1\n");
        return 0;
    }

    int S = sz[root];
    int u = -1;

    for (int x = comp_head[root]; x != 0; x = comp_next[x]) {
        if (deg[x] < S - 1) {
            u = x;
            break;
        }
    }

    if (u == -1) u = comp_head[root];

    char *mark = (char*)calloc(N + 1, sizeof(char));
    for (int e = head_adj[u]; e != -1; e = adj_next[e]) {
        mark[to[e]] = 1;
    }

    for (int x = comp_head[root]; x != 0; x = comp_next[x]) {
        if (x != u && !mark[x]) {
            printf("%d %d\n", u, x);
            return 0;
        }
    }

    printf("-1\n");
    return 0;
}
